// ============================================================================
// FreeLang HTTP Server: 네이티브 웹 서버
// 포트 3000에서 바인드, 정적 파일 + API 서빙
// ============================================================================

use "..core/state"
use "./router"

// ──────────────────────────────────────────────────────────────────────────
// 상수
// ──────────────────────────────────────────────────────────────────────────

const PORT = 3000
const LISTEN_ADDR = "127.0.0.1"
const MAX_REQUEST_SIZE = 1024 * 1024  // 1MB

// ──────────────────────────────────────────────────────────────────────────
// HTTP 요청/응답 타입
// ──────────────────────────────────────────────────────────────────────────

record HttpRequest {
  method: string        // "GET", "POST", "PUT", "DELETE", "PATCH"
  path: string
  query: map<string, string>
  headers: map<string, string>
  body: string
}

record HttpResponse {
  status: number
  headers: map<string, string>
  body: string
}

// ──────────────────────────────────────────────────────────────────────────
// 내장 정적 파일
// ──────────────────────────────────────────────────────────────────────────

func getEmbeddedFile(path: string) -> string? {
  match path {
    "/" | "/index.html" => return getIndexHtml()
    "/blog.html" => return getBlogHtml()
    "/freelang-bridge.js" => return getFreelangBridgeJs()
    "/main.js" => return getMainJs()
    "/style.css" => return getStyleCss()
    default => return null
  }
}

// ──────────────────────────────────────────────────────────────────────────
// HTML 임베드 (최소 구조)
// ──────────────────────────────────────────────────────────────────────────

func getIndexHtml() -> string {
  return `<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>FreeLang + JS 통합 예제</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            min-height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 20px;
        }

        .container {
            background: white;
            border-radius: 16px;
            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
            padding: 40px;
            max-width: 500px;
            width: 100%;
        }

        h1 {
            color: #333;
            margin-bottom: 30px;
            text-align: center;
            font-size: 2em;
        }

        .counter-display {
            font-size: 3em;
            font-weight: bold;
            text-align: center;
            color: #667eea;
            margin: 30px 0;
            font-family: 'Monaco', monospace;
        }

        .button-group {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 12px;
            margin: 30px 0;
        }

        button {
            padding: 12px 20px;
            font-size: 1em;
            border: none;
            border-radius: 8px;
            cursor: pointer;
            font-weight: 600;
            transition: all 0.3s ease;
        }

        .btn-primary {
            background: #667eea;
            color: white;
            grid-column: 1 / -1;
        }

        .btn-primary:hover {
            background: #5568d3;
            transform: translateY(-2px);
        }

        .btn-secondary {
            background: #f0f0f0;
            color: #333;
        }

        .btn-secondary:hover {
            background: #e0e0e0;
        }

        .stats {
            margin-top: 30px;
            padding: 20px;
            background: #f9f9f9;
            border-radius: 8px;
        }

        .stat-item {
            display: flex;
            justify-content: space-between;
            margin: 10px 0;
            font-size: 0.95em;
        }

        .stat-label {
            color: #666;
        }

        .stat-value {
            font-weight: bold;
            color: #667eea;
        }

        .loading {
            display: none;
            text-align: center;
            color: #999;
            margin: 20px 0;
        }

        .loading.active {
            display: block;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>🚀 FreeLang + JS</h1>

        <div class="counter-display" id="counter">0</div>

        <div class="button-group">
            <button class="btn-primary" id="btn-increment">+1 증가</button>
            <button class="btn-secondary" id="btn-decrement">-1 감소</button>
            <button class="btn-secondary" id="btn-reset">초기화</button>
        </div>

        <div class="loading" id="loading">
            처리 중...
        </div>

        <div class="stats">
            <div class="stat-item">
                <span class="stat-label">상태:</span>
                <span class="stat-value" id="status">준비됨</span>
            </div>
            <div class="stat-item">
                <span class="stat-label">요청:</span>
                <span class="stat-value" id="requests">0</span>
            </div>
